    <el-dialog v-model="loginOpen" :title="authMode === 'register' ? '注册校易淘' : '登录校易淘'" width="420px" align-center @closed="resetAuthForm">
      <div style="display:flex;gap:8px;margin-bottom:14px">
        <button type="button" class="text-button" :style="authMode === 'login' ? 'font-weight:700;border-bottom:2px solid #111;padding-bottom:4px' : 'opacity:.55;padding-bottom:4px'" @click="authMode = 'login'">登录</button>
        <button type="button" class="text-button" :style="authMode === 'register' ? 'font-weight:700;border-bottom:2px solid #111;padding-bottom:4px' : 'opacity:.55;padding-bottom:4px'" @click="authMode = 'register'">注册</button>
      </div>
      <form v-if="authMode === 'login'" class="dialog-form" @submit.prevent="submitLogin"><p class="dialog-lead">使用手机号登录，登录后即可发布闲置与下单。</p><label>手机号<input v-model="loginPhone" type="tel" inputmode="numeric" placeholder="请输入 11 位手机号" maxlength="11" required autocomplete="username"></label><label>密码<input v-model="loginPassword" type="password" placeholder="请输入密码" maxlength="64" required autocomplete="current-password"></label><p v-if="loginError" class="login-error" style="color:#c0392b;font-size:12px;margin:4px 0 0">{{ loginError }}</p><button class="primary-button full-width" type="submit" :disabled="loginLoading">{{ loginLoading ? '登录中…' : '登录' }} <Icon name="arrow" :size="18" /></button><div class="mode-note">还没有账号？<button type="button" class="text-button" style="text-decoration:underline" @click="authMode = 'register'">立即注册</button>　演示账号 13800001001 / admin123</div></form>
      <form v-else class="dialog-form" @submit.prevent="submitRegister"><p class="dialog-lead">注册后即可发布闲置、下单与收款，手机号就是登录账号。</p><label>手机号<input v-model="registerPhone" type="tel" inputmode="numeric" placeholder="请输入 11 位手机号" maxlength="11" required autocomplete="username"></label><label>昵称<input v-model="registerNickname" placeholder="选填，默认用手机号后四位" maxlength="20"></label><label>密码<input v-model="registerPassword" type="password" placeholder="6-20 位密码" maxlength="20" required autocomplete="new-password"></label><label>确认密码<input v-model="registerConfirm" type="password" placeholder="请再次输入密码" maxlength="20" required autocomplete="new-password"></label><p v-if="registerError" class="login-error" style="color:#c0392b;font-size:12px;margin:4px 0 0">{{ registerError }}</p><button class="primary-button full-width" type="submit" :disabled="registerLoading">{{ registerLoading ? '注册中…' : '注册并登录' }} <Icon name="arrow" :size="18" /></button><div class="mode-note">已有账号？<button type="button" class="text-button" style="text-decoration:underline" @click="authMode = 'login'">去登录</button></div></form>
    </el-dialog>

    <el-dialog v-model="detailOpen" :title="detail?.title || '商品详情'" width="780px" align-center>
      <div v-if="detail" class="detail-layout"><img v-if="detail.cover" :src="detail.cover" :alt="detail.title" style="width:100%;max-height:320px;object-fit:cover;border-radius:12px"><ProductArt v-else :type="detail.art" :background="detail.color" /><div class="detail-copy"><span class="detail-condition">{{ detail.condition }} · {{ detail.school }}</span><h2>{{ detail.title }}</h2><div class="detail-price"><span class="price"><small>¥</small>{{ detail.price }}</span><del v-if="detail.originalPrice">原价 ¥{{ detail.originalPrice }}</del></div><p>{{ detail.description }}</p><div class="detail-seller"><span class="avatar">{{ detail.avatar }}</span><strong>{{ detail.seller }}</strong><span>演示卖家</span></div><p class="detail-location"><Icon name="location" :size="16" /> {{ detail.location }}</p><div class="detail-actions"><button class="secondary-button" @click="toggleFavorite(detail.id)"><Icon name="heart" :size="17" />{{ favorites.includes(detail.id) ? '已收藏' : '收藏' }}</button><button class="primary-button" @click="addCart(detail)"><Icon name="cart" :size="18" /> 加入购物车</button></div><small class="muted">演示商品不代表真实在售，正式购买功能尚未接入。</small></div></div>
    </el-dialog>

    <el-dialog v-model="publishOpen" title="让你的闲置，遇见新主人" width="560px" align-center>
      <form class="dialog-form" @submit.prevent="submitPublish"><div class="mode-note">发布后进入「待审核」，管理员通过后才会出现在商品列表。</div><label>商品名称<input v-model="publish.title" required minlength="4" maxlength="60" placeholder="给你的好物起个名字"></label><div class="form-row"><label>分类<select v-model="publish.category"><option v-for="c in categories.filter(c => c.id !== 'all')" :key="c.id" :value="c.id">{{ c.label }}</option></select></label><label>成色<select v-model="publish.condition"><option>几乎全新</option><option>九成新</option><option>八成新</option></select></label></div><div class="form-row"><label>转让价格（元）<input v-model="publish.price" type="number" min="0.01" max="99999" step="0.01" required placeholder="0.00"></label><label>交接地点<input v-model="publish.location" maxlength="40" required placeholder="如：图书馆南门"></label></div><label>商品图片<input type="file" accept="image/png,image/jpeg,image/gif,image/bmp" :disabled="publishUploading" @change="e => uploadPublishImage(e.target.files && e.target.files[0])"><small class="muted">{{ publishUploading ? '上传中…' : (publishImage ? '已上传 1 张，可重新选择替换' : '可选，支持 jpg/png/gif/bmp，≤5MB') }}</small></label><img v-if="publishImage" :src="publishImage" alt="图片预览" style="width:100%;max-height:220px;object-fit:cover;border-radius:10px;margin:4px 0"><label>商品描述<textarea v-model="publish.description" rows="4" minlength="10" maxlength="500" required placeholder="说说使用情况、配件和需要注意的小细节。"></textarea></label><button class="primary-button full-width" type="submit" :disabled="publishUploading"><Icon name="plus" :size="18" />发布并上架</button></form>
    </el-dialog>

    <el-dialog v-model="checkoutOpen" title="确认订单" width="500px" align-center>
      <form class="dialog-form" @submit.prevent="submitOrder"><div class="mode-note">提交后将按卖家拆分为多个订单（每个卖家一笔），金额与库存以后端为准。</div><label>收货人<input v-model="receiver" maxlength="20" required placeholder="请输入真实收货人"></label><label>手机号<input v-model="contact" inputmode="numeric" maxlength="11" required placeholder="11 位手机号"></label><label>收货地址<input v-model="address" maxlength="100" required placeholder="如：本校西区 3 号楼"></label><label>备注<textarea v-model="remark" rows="2" maxlength="200" placeholder="给卖家留言（选填）"></textarea></label><div class="checkout-summary">已选 {{ selectedItems.length }} 件商品<strong>¥{{ money(total) }}</strong></div><button class="primary-button full-width" type="submit" :disabled="submittingOrder">{{ submittingOrder ? '提交中…' : '提交订单' }} <Icon name="arrow" :size="18" /></button></form>
    </el-dialog>
  </div>
</template>